import { load } from "unity-asset-reader";
import {
  initTexture,
  isImage,
  imageInfo,
  decodeImage,
  encodePng,
} from "unity-asset-reader-texture";
import { zipSync, unzipSync } from "fflate";

const WASM_PATH = new URL("./wasm/", import.meta.url).href;

const UNITY_MAGICS = ["UnityFS", "UnityWeb", "UnityRaw"];

/** Strip any bytes before UnityFS / UnityWeb / UnityRaw magic. */
function normalizeBundleBytes(bytes) {
  const u8 = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  for (const m of UNITY_MAGICS) {
    const enc = new TextEncoder().encode(m);
    outer: for (let i = 0; i <= Math.min(64, u8.length - enc.length); i++) {
      for (let j = 0; j < enc.length; j++) {
        if (u8[i + j] !== enc[j]) continue outer;
      }
      if (i === 0) return u8;
      return u8.subarray(i);
    }
  }
  return u8;
}

function looksLikeUnityBundle(bytes) {
  const u8 = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  if (u8.length < 16) return false;
  for (const m of UNITY_MAGICS) {
    const enc = new TextEncoder().encode(m);
    outer: for (let i = 0; i <= Math.min(64, u8.length - enc.length); i++) {
      for (let j = 0; j < enc.length; j++) {
        if (u8[i + j] !== enc[j]) continue outer;
      }
      return true;
    }
  }
  return false;
}

function isZipBytes(bytes) {
  return bytes.length >= 4 && bytes[0] === 0x50 && bytes[1] === 0x4b;
}

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

function safeFilename(name) {
  return String(name || "image")
    .replace(/[\\/:*?"<>|]+/g, "_")
    .replace(/^\.+/, "_")
    .slice(0, 120) || "image";
}

function basename(path) {
  const s = String(path || "").replace(/\\/g, "/");
  const i = s.lastIndexOf("/");
  return i >= 0 ? s.slice(i + 1) : s;
}

function stem(name) {
  const b = basename(name);
  const i = b.lastIndexOf(".");
  return i > 0 ? b.slice(0, i) : b;
}

function yieldToUi() {
  return new Promise((r) => setTimeout(r, 0));
}

const state = {
  ready: false,
  busy: false,
  items: [], // { sourceName, name, type, width, height, formatName, pngBytes, thumbUrl, fullUrl }
  errors: [], // { sourceName, message }
  label: "",
};

const $ = (sel) => document.querySelector(sel);

function setStatus(msg, kind = "") {
  const el = $("#status");
  el.textContent = msg || "";
  el.dataset.kind = kind;
}

function showProgress(show, label = "") {
  const wrap = $("#progress-wrap");
  wrap.hidden = !show;
  if (label) $("#progress-label").textContent = label;
}

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function renderGrid() {
  const grid = $("#grid");
  grid.innerHTML = "";
  $("#actions").hidden = state.items.length === 0;
  $("#empty").hidden = state.items.length > 0 || state.errors.length > 0;

  const errorsEl = $("#errors");
  if (state.errors.length) {
    errorsEl.hidden = false;
    errorsEl.innerHTML =
      `<div class="errors-title">スキップ / エラー (${state.errors.length})</div>` +
      state.errors
        .map(
          (e) =>
            `<div class="error-row"><strong>${escapeHtml(e.sourceName)}</strong>: ${escapeHtml(e.message)}</div>`
        )
        .join("");
  } else {
    errorsEl.hidden = true;
    errorsEl.innerHTML = "";
  }

  // Group by source file
  const groups = new Map();
  for (const [i, item] of state.items.entries()) {
    const key = item.sourceName || "(unknown)";
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push({ item, index: i });
  }

  for (const [source, entries] of groups) {
    const section = document.createElement("section");
    section.className = "group";
    section.innerHTML = `<h3 class="group-title">${escapeHtml(source)} <span class="group-count">${entries.length} 枚</span></h3>`;
    const cards = document.createElement("div");
    cards.className = "group-grid";
    for (const { item, index } of entries) {
      const card = document.createElement("button");
      card.type = "button";
      card.className = "card";
      card.innerHTML = `
        <img src="${item.thumbUrl}" alt="${escapeHtml(item.name)}" loading="lazy" />
        <div class="meta">
          <div class="name">${escapeHtml(item.name)}</div>
          <div class="sub">${item.width}×${item.height} · ${escapeHtml(item.formatName)} · ${item.type}</div>
        </div>
      `;
      card.addEventListener("click", () => openLightbox(index));
      cards.appendChild(card);
    }
    section.appendChild(cards);
    grid.appendChild(section);
  }
}

function openLightbox(index) {
  const item = state.items[index];
  if (!item) return;
  const lb = $("#lightbox");
  $("#lb-img").src = item.fullUrl;
  $("#lb-title").textContent = item.name;
  $("#lb-info").textContent = `${item.sourceName} · ${item.width}×${item.height} · ${item.formatName} · ${item.type}`;
  lb.hidden = false;
  lb.dataset.index = String(index);
  document.body.style.overflow = "hidden";
}

function closeLightbox() {
  $("#lightbox").hidden = true;
  document.body.style.overflow = "";
}

function clearItems() {
  for (const it of state.items) {
    if (it.fullUrl) URL.revokeObjectURL(it.fullUrl);
    if (it.thumbUrl && String(it.thumbUrl).startsWith("blob:")) URL.revokeObjectURL(it.thumbUrl);
  }
  state.items = [];
  state.errors = [];
  state.label = "";
  renderGrid();
}

/**
 * Decode one Unity bundle buffer into image items. Releases large intermediates.
 * @returns {{ items: object[], error?: string }}
 */
async function extractImagesFromBytes(bytes, sourceName) {
  if (!looksLikeUnityBundle(bytes)) {
    return { items: [], error: "UnityFS / UnityWeb / UnityRaw 形式ではありません" };
  }
  let env;
  try {
    env = load(normalizeBundleBytes(bytes));
  } catch (e) {
    return { items: [], error: e.message || String(e) };
  }

  const images = [];
  for (const asset of env.assets()) {
    if (isImage(asset)) images.push(asset);
  }

  const seen = new Set();
  const unique = [];
  for (const a of images) {
    const info = imageInfo(a);
    const key = `${a.type}:${info.name}:${info.pathId}`;
    if (!seen.has(key)) {
      seen.add(key);
      unique.push(a);
    }
  }

  const textures = unique.filter((a) => a.type === "Texture2D");
  const sprites = unique.filter((a) => a.type === "Sprite");
  const texNames = new Set(
    textures.map((a) => {
      const i = imageInfo(a);
      return `${i.name}|${i.width}x${i.height}`;
    })
  );
  const finalAssets = [
    ...textures,
    ...sprites.filter((a) => {
      const i = imageInfo(a);
      return !texNames.has(`${i.name}|${i.width}x${i.height}`);
    }),
  ];

  if (finalAssets.length === 0) {
    return { items: [], error: "画像（Texture2D / Sprite）が見つかりませんでした" };
  }

  const items = [];
  for (let i = 0; i < finalAssets.length; i++) {
    const asset = finalAssets[i];
    await yieldToUi();
    const info = imageInfo(asset);
    const decoded = await decodeImage(asset);
    const pngBytes = encodePng({
      data: decoded.rgba,
      width: decoded.width,
      height: decoded.height,
    });
    const thumbUrl = await makeThumb(decoded.rgba, decoded.width, decoded.height, 360);
    // Drop decoded RGBA ASAP
    decoded.rgba = null;

    const pngBlob = new Blob([pngBytes], { type: "image/png" });
    const fullUrl = URL.createObjectURL(pngBlob);

    items.push({
      sourceName,
      name: info.name || asset.name || `image_${i}`,
      type: asset.type,
      width: decoded.width,
      height: decoded.height,
      formatName: info.formatName || String(info.format),
      pngBytes,
      thumbUrl,
      fullUrl,
    });
  }
  return { items };
}

async function makeThumb(rgba, w, h, maxSide) {
  const scale = Math.min(1, maxSide / Math.max(w, h));
  const tw = Math.max(1, Math.round(w * scale));
  const th = Math.max(1, Math.round(h * scale));
  const canvas = document.createElement("canvas");
  canvas.width = tw;
  canvas.height = th;
  const ctx = canvas.getContext("2d");
  const full = document.createElement("canvas");
  full.width = w;
  full.height = h;
  full.getContext("2d").putImageData(new ImageData(new Uint8ClampedArray(rgba), w, h), 0, 0);
  ctx.imageSmoothingEnabled = true;
  ctx.drawImage(full, 0, 0, tw, th);
  // Prefer blob URL over huge data URL when possible
  return new Promise((resolve) => {
    canvas.toBlob(
      (blob) => {
        if (blob) resolve(URL.createObjectURL(blob));
        else resolve(canvas.toDataURL("image/jpeg", 0.85));
      },
      "image/jpeg",
      0.85
    );
  });
}

/**
 * Expand a File list into work units { name, getBytes() }.
 * Zip files are expanded into their entries (non-directory).
 */
async function expandInputs(files) {
  /** @type {{ name: string, getBytes: () => Promise<Uint8Array> }[]} */
  const units = [];
  for (const file of files) {
    const name = file.webkitRelativePath || file.name;
    const lower = name.toLowerCase();
    if (lower.endsWith(".zip")) {
      const buf = new Uint8Array(await file.arrayBuffer());
      if (!isZipBytes(buf)) {
        units.push({
          name,
          getBytes: async () => buf,
        });
        continue;
      }
      let entries;
      try {
        entries = unzipSync(buf);
      } catch (e) {
        units.push({
          name,
          getBytes: async () => {
            throw new Error(`ZIP を展開できません: ${e.message || e}`);
          },
        });
        continue;
      }
      const zipStem = stem(basename(name));
      for (const [entryName, data] of Object.entries(entries)) {
        if (entryName.endsWith("/")) continue;
        const base = basename(entryName);
        if (!base || base.startsWith(".")) continue;
        // Capture data in closure; fflate gives Uint8Array
        const entryData = data;
        units.push({
          name: `${zipStem}/${entryName}`,
          getBytes: async () => entryData,
        });
      }
    } else {
      units.push({
        name: basename(name) || name,
        getBytes: async () => new Uint8Array(await file.arrayBuffer()),
      });
    }
  }
  return units;
}

async function processFiles(fileList) {
  if (!state.ready) {
    setStatus("初期化中です。少し待ってから再度お試しください。", "err");
    return;
  }
  if (state.busy) return;
  const files = Array.from(fileList || []).filter(Boolean);
  if (!files.length) return;

  state.busy = true;
  clearItems();
  state.label = files.length === 1 ? files[0].name : `${files.length} 件の入力`;
  $("#file-label").textContent = state.label;

  try {
    showProgress(true, "入力を準備しています…");
    const units = await expandInputs(files);
    if (!units.length) {
      setStatus("処理対象のファイルがありません", "err");
      return;
    }

    let okFiles = 0;
    let imageCount = 0;

    for (let i = 0; i < units.length; i++) {
      const unit = units[i];
      showProgress(true, `${i + 1} / ${units.length} 件処理中: ${unit.name}`);
      await yieldToUi();

      let bytes;
      try {
        bytes = await unit.getBytes();
      } catch (e) {
        state.errors.push({ sourceName: unit.name, message: e.message || String(e) });
        continue;
      }

      try {
        const { items, error } = await extractImagesFromBytes(bytes, basename(unit.name) || unit.name);
        // Release source buffer
        bytes = null;
        if (error) {
          state.errors.push({ sourceName: unit.name, message: error });
        } else {
          okFiles++;
          imageCount += items.length;
          state.items.push(...items);
          renderGrid();
        }
      } catch (e) {
        console.error(e);
        state.errors.push({ sourceName: unit.name, message: e.message || String(e) });
      }
    }

    renderGrid();
    const parts = [];
    parts.push(`${okFiles} ファイルから ${imageCount} 枚の画像`);
    if (state.errors.length) parts.push(`エラー ${state.errors.length} 件`);
    setStatus(parts.join(" · "), state.errors.length && !imageCount ? "err" : "ok");
  } catch (e) {
    console.error(e);
    setStatus(`エラー: ${e.message || e}`, "err");
  } finally {
    showProgress(false);
    state.busy = false;
  }
}

function downloadOne(index) {
  const item = state.items[index];
  if (!item) return;
  downloadBlob(
    new Blob([item.pngBytes], { type: "image/png" }),
    `${safeFilename(item.name)}.png`
  );
}

function downloadAllZip() {
  if (!state.items.length) return;
  const files = {};
  const used = new Set();
  for (const item of state.items) {
    const folder = safeFilename(stem(item.sourceName) || "images");
    let base = safeFilename(item.name);
    let path = `${folder}/${base}.png`;
    let n = 2;
    while (used.has(path)) {
      path = `${folder}/${base}_${n}.png`;
      n++;
    }
    used.add(path);
    files[path] = item.pngBytes;
  }
  const zipped = zipSync(files, { level: 6 });
  const zipName =
    safeFilename(stem(state.label) || `images_${state.items.length}`) + "_export.zip";
  downloadBlob(new Blob([zipped], { type: "application/zip" }), zipName);
}

/** Collect File objects from a drop event (files + recursive directories). */
async function collectDroppedFiles(dataTransfer) {
  const out = [];
  const items = dataTransfer?.items;
  if (items && items.length) {
    const entries = [];
    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      if (item.kind !== "file") continue;
      // Prefer File System Access API handle if available
      if (typeof item.getAsFileSystemHandle === "function") {
        try {
          const handle = await item.getAsFileSystemHandle();
          if (handle) {
            await walkHandle(handle, "", out);
            continue;
          }
        } catch {
          /* fall through */
        }
      }
      const entry = item.webkitGetAsEntry?.();
      if (entry) {
        entries.push(entry);
        continue;
      }
      const f = item.getAsFile?.();
      if (f) out.push(f);
    }
    for (const entry of entries) {
      await walkEntry(entry, out);
    }
    if (out.length) return out;
  }
  // Fallback: flat FileList
  return Array.from(dataTransfer?.files || []);
}

async function walkHandle(handle, pathPrefix, out) {
  if (handle.kind === "file") {
    const file = await handle.getFile();
    const name = pathPrefix ? `${pathPrefix}/${file.name}` : file.name;
    // Attach relative path-like name for display
    Object.defineProperty(file, "webkitRelativePath", { value: name });
    out.push(file);
    return;
  }
  if (handle.kind === "directory") {
    const prefix = pathPrefix ? `${pathPrefix}/${handle.name}` : handle.name;
    for await (const entry of handle.values()) {
      await walkHandle(entry, prefix, out);
    }
  }
}

function walkEntry(entry, out) {
  return new Promise((resolve, reject) => {
    if (entry.isFile) {
      entry.file(
        (file) => {
          Object.defineProperty(file, "webkitRelativePath", {
            value: entry.fullPath?.replace(/^\//, "") || file.name,
          });
          out.push(file);
          resolve();
        },
        reject
      );
    } else if (entry.isDirectory) {
      const reader = entry.createReader();
      const readBatch = () => {
        reader.readEntries(async (results) => {
          if (!results.length) {
            resolve();
            return;
          }
          try {
            for (const child of results) {
              await walkEntry(child, out);
            }
            readBatch();
          } catch (e) {
            reject(e);
          }
        }, reject);
      };
      readBatch();
    } else {
      resolve();
    }
  });
}

function supportsDirectoryPicker() {
  // webkitdirectory is widely available on desktop; unreliable/absent as a useful UX on iOS Safari
  const input = document.createElement("input");
  input.type = "file";
  const supported = "webkitdirectory" in input;
  const ua = navigator.userAgent || "";
  const isMobile = /iPhone|iPad|iPod|Android/i.test(ua);
  return supported && !isMobile;
}

async function init() {
  setStatus("テクスチャデコーダを読み込み中…");
  try {
    await initTexture({ wasmPath: WASM_PATH });
    state.ready = true;
    setStatus("アセットバンドルやフォルダ、ZIP を選んでください（複数可）");
  } catch (e) {
    console.error(e);
    setStatus(`初期化に失敗しました: ${e.message || e}`, "err");
  }
}

function setupUI() {
  const input = $("#file");
  const folderInput = $("#folder");
  const drop = $("#drop");

  input.multiple = true;

  $("#pick-btn").addEventListener("click", () => input.click());
  input.addEventListener("change", () => {
    const list = input.files;
    if (list?.length) processFiles(list);
    input.value = "";
  });

  const folderSupported = supportsDirectoryPicker();
  const folderBtn = $("#folder-btn");
  const folderHint = $("#folder-hint");
  if (folderSupported) {
    folderBtn.hidden = false;
    folderHint.hidden = true;
    folderBtn.addEventListener("click", () => folderInput.click());
    folderInput.addEventListener("change", () => {
      const list = folderInput.files;
      if (list?.length) processFiles(list);
      folderInput.value = "";
    });
  } else {
    folderBtn.hidden = true;
    folderHint.hidden = false;
  }

  drop.addEventListener("dragover", (e) => {
    e.preventDefault();
    drop.classList.add("drag");
  });
  drop.addEventListener("dragleave", () => drop.classList.remove("drag"));
  drop.addEventListener("drop", async (e) => {
    e.preventDefault();
    drop.classList.remove("drag");
    try {
      const files = await collectDroppedFiles(e.dataTransfer);
      if (files.length) processFiles(files);
    } catch (err) {
      console.error(err);
      setStatus(`ドロップの読み取りに失敗: ${err.message || err}`, "err");
    }
  });

  $("#btn-zip").addEventListener("click", downloadAllZip);
  $("#btn-clear").addEventListener("click", () => {
    clearItems();
    $("#file-label").textContent = "ファイル未選択";
    setStatus("アセットバンドルやフォルダ、ZIP を選んでください（複数可）");
  });

  $("#lb-close").addEventListener("click", closeLightbox);
  $("#lb-backdrop").addEventListener("click", closeLightbox);
  $("#lb-download").addEventListener("click", () => {
    const i = Number($("#lightbox").dataset.index);
    downloadOne(i);
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") closeLightbox();
  });

  if ("serviceWorker" in navigator) {
    navigator.serviceWorker.register("./sw.js").catch(() => {});
  }
}

setupUI();
init();
